search-engine.pseudocode:
def build_index(docs):  # docs: {문서ID: 단어 목록}
    index = {}  # 역색인: 단어 -> {문서ID: 빈도}
    for d, words in docs.items():
        for w in words:
            index.setdefault(w, {})
            index[w][d] = index[w].get(d, 0) + 1
    return index

def search(query, index, n_docs):  # TF-IDF 점수 순위화
    scores = {}
    for w in query:
        postings = index.get(w, {})
        if not postings:
            continue
        idf = log(n_docs / len(postings))  # 희귀 단어일수록 큼
        for d, tf in postings.items():
            scores[d] = scores.get(d, 0) + tf * idf
    return sorted(scores, key=scores.get, reverse=True)

secant-method.pseudocode:
def secant(f, x0, x1, eps=1e-10, max_iter=50):
    for _ in range(max_iter):
        f0, f1 = f(x0), f(x1)
        if f1 == f0:
            raise ZeroDivisionError('수평 할선')
        x2 = x1 - f1 * (x1 - x0) / (f1 - f0)  # 할선의 x절편
        if abs(x2 - x1) < eps:
            return x2
        x0, x1 = x1, x2  # 최근 두 점으로 갱신
    return x1  # 최대 반복 도달

print(secant(lambda x: x * x - 2, 1.0, 2.0))  # √2 ≈ 1.41421

second-chance-algorithm.pseudocode:
def access(queue, ref, page, capacity):
    if page in queue:
        ref[page] = 1  # 적중: 참조 비트만 설정
        return 'hit'
    if len(queue) == capacity:
        while True:
            victim = queue.pop(0)  # FIFO 맨 앞
            if ref[victim] == 1:
                ref[victim] = 0  # 비트 해제 후 한 번 더 기회
                queue.append(victim)
            else:
                del ref[victim]  # 비트 0 → 교체
                break
    queue.append(page)
    ref[page] = 1  # 적재 시 참조됨
    return 'fault'

secret-sharing.pseudocode:
def split(secret, t, n, prime):
    # t-1차 다항식: f(0)=secret, 나머지 계수는 난수
    coef = [secret] + [random_int(1, prime - 1)
                       for _ in range(t - 1)]
    def f(x):
        return sum(c * pow(x, k, prime)
                   for k, c in enumerate(coef)) % prime
    return [(i, f(i)) for i in range(1, n + 1)]

def recover(shares, prime):
    # t개 이상 조각으로 라그랑주 보간 → f(0)
    secret = 0
    for i, (xi, yi) in enumerate(shares):
        num, den = 1, 1
        for j, (xj, _) in enumerate(shares):
            if i != j:
                num = num * (-xj) % prime
                den = den * (xi - xj) % prime
        secret += yi * num * pow(den, -1, prime)
    return secret % prime

selection-pressure.pseudocode:
def tournament_select(pop, fitness, k):
    # k가 클수록 선택압 증가 (k=1이면 무작위 선택)
    contestants = [random_choice(pop) for _ in range(k)]
    return max(contestants, key=fitness)

def roulette_select(pop, fitness):  # 적합도 비례 선택
    total = sum(fitness(x) for x in pop)
    r = random_uniform(0, total)
    acc = 0
    for x in pop:
        acc += fitness(x)
        if acc >= r:
            return x
    return pop[-1]

selection-sort.pseudocode:
def selection_sort(a):
    n = len(a)
    for i in range(n - 1):
        m = i  # 미정렬 구간의 최소값 위치
        for j in range(i + 1, n):
            if a[j] < a[m]:
                m = j
        if m != i:
            a[i], a[m] = a[m], a[i]  # 교환 최대 n-1회
    return a  # 비교 항상 n(n-1)/2회 → O(n²)

self-balancing-binary-search-tree.pseudocode:
def rotate_right(y):
    x = y.left
    y.left = x.right
    x.right = y
    update_height(y)
    update_height(x)
    return x  # 새 서브트리 루트 (rotate_left는 대칭)

def rebalance(n):  # AVL 기준, 삽입·삭제 경로마다 호출
    update_height(n)
    bf = height(n.left) - height(n.right)
    if bf > 1:  # 왼쪽 과중
        if height(n.left.left) < height(n.left.right):
            n.left = rotate_left(n.left)  # LR → LL
        return rotate_right(n)
    if bf < -1:  # 오른쪽 과중
        if height(n.right.right) < height(n.right.left):
            n.right = rotate_right(n.right)  # RL → RR
        return rotate_left(n)
    return n

self-healing.pseudocode:
def reconcile(desired, list_pods, create_pod, delete_pod):
    while True:  # 컨트롤러 조정 루프
        pods = [p for p in list_pods() if p.healthy]
        for p in list_pods():
            if not p.healthy:
                delete_pod(p)  # 실패 Pod 제거
        for _ in range(max(desired - len(pods), 0)):
            create_pod()  # 부족분 생성 (가용 노드에 배치)
        for p in pods[desired:]:
            delete_pod(p)  # 초과분 삭제
        wait_for_change()  # 상태 변화 감시 후 반복

semi-supervised-learning.pseudocode:
def self_training(labeled, unlabeled, train, predict,
                  th=0.9, rounds=5):  # 자기학습
    model = train(labeled)
    for _ in range(rounds):
        rest = []
        for x in unlabeled:
            label, prob = predict(model, x)
            if prob >= th:  # 고신뢰 예측만 의사 라벨로 채택
                labeled.append((x, label))
            else:
                rest.append(x)
        if len(rest) == len(unlabeled):
            break  # 추가된 샘플 없음 → 종료
        unlabeled = rest
        model = train(labeled)  # 확장된 데이터로 재학습
    return model

separate-chaining.pseudocode:
class ChainedHash:
    def __init__(self, m):
        self.m = m
        self.table = [[] for _ in range(m)]  # 버킷별 체인

    def insert(self, key, val):
        chain = self.table[key % self.m]
        for i, (k, _) in enumerate(chain):
            if k == key:
                chain[i] = (key, val)  # 같은 키면 갱신
                return
        chain.append((key, val))  # 충돌해도 체인에 연결

    def search(self, key):
        for k, v in self.table[key % self.m]:  # 체인 순회
            if k == key:
                return v
        return None

    def delete(self, key):
        b = key % self.m  # 포인터 조정만으로 삭제
        self.table[b] = [e for e in self.table[b]
                         if e[0] != key]

sequential-pattern-mining.pseudocode:
def prefixspan(db, min_sup, prefix=None, out=None):
    # db: 시퀀스 목록 (각 시퀀스는 시간순 항목 리스트)
    prefix = prefix or []
    out = [] if out is None else out
    counts = {}
    for seq in db:
        for item in set(seq):  # 시퀀스당 1회만 계수
            counts[item] = counts.get(item, 0) + 1
    for item, sup in counts.items():
        if sup < min_sup:
            continue
        pattern = prefix + [item]
        out.append((pattern, sup))
        projected = []  # item 첫 등장 이후의 접미 시퀀스
        for seq in db:
            if item in seq:
                suffix = seq[seq.index(item) + 1:]
                if suffix:
                    projected.append(suffix)
        prefixspan(projected, min_sup, pattern, out)
    return out

serializability.pseudocode:
def conflict_serializable(schedule):  # [(txn, op, item)]
    edges = set()
    for i, (ti, opi, xi) in enumerate(schedule):
        for tj, opj, xj in schedule[i + 1:]:
            # 같은 항목·다른 트랜잭션·쓰기 포함 → 충돌
            if xi == xj and ti != tj and 'W' in (opi, opj):
                edges.add((ti, tj))  # ti → tj 선행
    txns = {t for t, _, _ in schedule}
    indeg = {t: 0 for t in txns}
    for _, b in edges:
        indeg[b] += 1
    ready = [t for t in txns if indeg[t] == 0]
    order = []
    while ready:  # 위상 정렬로 사이클 검사
        u = ready.pop()
        order.append(u)
        for a, b in edges:
            if a == u:
                indeg[b] -= 1
                if indeg[b] == 0:
                    ready.append(b)
    if len(order) < len(txns):
        return None  # 사이클 → 충돌 직렬 불가
    return order  # 동등한 직렬 실행 순서
